-- Supplier pages beyond Melbourne: Australia's other cities, London and New
-- York, the brands they carry, and maker pages for those brands (after
-- 20261017720100 adds supplier pages). Step 6f of the bottle catalog plan:
-- https://claude.ai/artifact/Vu6seuSNtN42nKYb2nDCVR
--
--   * 82 suppliers, each checked on its own site. 64 in Australia: the
--     national drinks groups' Australian arms, and suppliers to venues in
--     Sydney, Brisbane, Perth, Adelaide, Hobart and Canberra (spirits, wine
--     and beer distributors and importers, ice, fresh produce and garnish,
--     glassware, barware and equipment). 9 in London and 9 in New York:
--     drinks distributors, importers and wholesalers, an ice supplier
--     and two barware suppliers. Each gets an unclaimed, public
--     supplier page in its own country, saying what it supplies and the
--     cities its own site says it serves. Business names only. Brand owners
--     whose brands another company distributes, and suppliers that already
--     have a maker page for what they deliver, are left out.
--   * 358 supplier lines: whose brands each supplier carries, in its
--     country or in one state, each with the supplier's page that says so.
--     A brand links to its maker's page: an existing page when the name
--     matches (or the brand is a product line of that maker), else a brand
--     checked on its own site.
--   * 84 new maker pages for the brands that had none, each checked on the
--     brand's own site, or an importer's or retailer's page when the brand
--     has no readable site (name, website, what it makes, and the country
--     only where a page shows it). A brand that is a supplier's own label,
--     that wasn't confirmed, or whose maker rests only on a distributor's
--     list gets no page and no line.
--   * Independent checks: every supplier (4 wrong facts in 465), every new
--     maker page (5 wrong in 326), 60 random lines to existing makers (1
--     wrong in 179) and 60 random lines to new makers (5 wrong in 179). All
--     fixed; Bandwagon Beverages' brands are Australia-wide, not Victoria
--     only, across all its lines.
--   * Not here yet: about 2,100 London and New York portfolio lines, mostly
--     wine estates with no maker page; they need maker pages first.
--
-- Matched by name; a second run changes nothing more.

CREATE TEMP TABLE maker_in (name text PRIMARY KEY, handle text NOT NULL, website text, country text, makes text[] NOT NULL);

-- A page per maker, unclaimed, public. A handle someone already uses, or a
-- maker that already has a page by this name, is left alone.
SELECT 'maker', m.handle, m.name, m.website, m.country, m.makes, true
  FROM maker_in m
 WHERE NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.handle = m.handle)
   AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.kind = 'maker' AND lower(p.display_name) = lower(m.name));

-- A maker page an earlier load made gains what this one says it makes.
UPDATE public.profiles p SET makes = ARRAY(SELECT DISTINCT unnest(p.makes || m.makes) ORDER BY 1)
  FROM maker_in m
 WHERE p.kind = 'maker' AND lower(p.display_name) = lower(m.name) AND NOT (m.makes <@ p.makes);

CREATE TEMP TABLE supplier_in (name text PRIMARY KEY, handle text NOT NULL, website text, country text NOT NULL, supplies text[] NOT NULL, serves text[] NOT NULL);

-- A page per supplier, unclaimed, public.
SELECT 'supplier', s.handle, s.name, s.website, s.country, s.supplies, s.serves, true
  FROM supplier_in s
 WHERE NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.handle = s.handle)
   AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.kind = 'supplier' AND lower(p.display_name) = lower(s.name));

CREATE TEMP TABLE line_in (supplier text NOT NULL, maker text NOT NULL, region text NOT NULL, source_url text NOT NULL);

-- Whose brands each supplier carries, and where, with the page that says so.
-- A line whose supplier or maker has no page is skipped.
SELECT DISTINCT ON (s.id, m.id, l.region) s.id, m.id, l.region, l.source_url
  FROM line_in l
  JOIN public.profiles s ON s.kind = 'supplier' AND lower(s.display_name) = lower(l.supplier)
  JOIN public.profiles m ON m.kind = 'maker' AND lower(m.display_name) = lower(l.maker)
 ORDER BY s.id, m.id, l.region, m.created_at
ON CONFLICT ON CONSTRAINT "supplier_lines_one_per_region" DO NOTHING;

DROP TABLE maker_in, supplier_in, line_in;
